package io.github.diodeme.ji.telemetry;

import java.util.Map;

/** Structured point-in-time event within a span. */
public record TelemetryEvent(String name, Map<String, TelemetryValue> attributes) {
    public TelemetryEvent {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("event name must not be blank");
        attributes = Map.copyOf(attributes);
    }
}
